    MARTIAL_CATEGORIES,
    MARTIAL_TALENT_STEPS,
    BEAST_SPECIES_STEPS,
    conditions: Object.freeze(conditions),
    effects: Object.freeze(effects),
    customHandlers: Object.freeze(customHandlers),
    flowResolvers: Object.freeze(flowResolvers),
